-- Function: public.fn_get_filtered_experience_schedules
-- Backup generated on 2026-10-25 20:33:23

CREATE OR REPLACE FUNCTION public.fn_get_filtered_experience_schedules(p_tenant_id uuid, p_date date, p_organization_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(id uuid, tenant_id uuid, experience_id uuid, classroom_id uuid, scheduled_date date, time_of_day character varying, status character varying, planned_start_time time without time zone, planned_end_time time without time zone, preparation_notes text)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT s.id, s.tenant_id, s.experience_id,             s.classroom_id, s.scheduled_date,             s.time_of_day, s.status, s.planned_start_time,             s.planned_end_time, s.preparation_notes     FROM experience_schedules s     JOIN classrooms c ON s.classroom_id = c.id     JOIN branches b ON c.branch_id = b.id     WHERE s.tenant_id = p_tenant_id       AND (p_organization_id IS NULL OR b.organization_id = p_organization_id)       AND s.scheduled_date = p_date       AND (p_classroom_id IS NULL OR s.classroom_id = p_classroom_id)       AND (p_branch_id IS NULL OR c.branch_id = p_branch_id)     ORDER BY s.planned_start_time ASC NULLS LAST, s.time_of_day ASC; END; $function$ ;
